    "pt": "【Activate･Main】<Support 3> (Coloque esta Unidade em Rest. Outra Unidade aliada recebe AP+(quantidade especificada) durante este turno.)\n【During Pair･(Coordinator) Pilot】【Once per Turn】Quando voce usar o <Support> desta Unidade para aumentar o AP de uma Unidade (ZAFT), coloque esta Unidade como active.",
