  "GD04-015": {
    "pt": "【Deploy】Escolha 1 das suas Unidades (League Militaire) ativas e 1 Unidade inimiga de Lv.3 ou menor. Coloque-as em Rest.",
    "en": "【Deploy】Choose 1 of your active (League Militaire) Units and 1 enemy Unit that is Lv.3 or lower. Rest them."
  },
  "GD04-016": {
    "pt": "<Blocker> (Coloque esta Unidade em Rest para mudar o alvo do ataque para ela.)\nEsta Unidade não pode escolher o jogador inimigo como alvo de ataque.",
    "en": "<Blocker> (Rest this Unit to change the attack target to it.)\nThis Unit can't choose the enemy player as its attack target."
  },
  "GD04-017": {
    "pt": "【When Paired･(Newtype) Pilot】Faça o Deploy de 2 fichas de Unidade [Wire-Guided Arm]((Zeon)･AP2･HP1･This Unit can't be paired with a Pilot).\n【Destroyed】Faça o Deploy de 1 ficha de Unidade [Zeong (Head)]((Zeon)･AP3･HP1) descansada.",
    "en": "【When Paired･(Newtype) Pilot】Deploy 2 [Wire-Guided Arm]((Zeon)･AP2･HP1･This Unit can't be paired with a Pilot) Unit tokens.\n【Destroyed】Deploy 1 rested [Zeong (Head)]((Zeon)･AP3･HP1) Unit token."
  },
  "GD04-018": {
    "pt": "<Breach 5> (Quando o ataque desta Unidade destruir uma Unidade inimiga, cause a quantidade especificada de dano à primeira carta na área de escudo daquele oponente.)\n【Once per Turn】Durante o seu turno, quando uma das suas outras Unidades (Academy) receber dano de um inimigo, coloque 1 EX Resource.",
    "en": "<Breach 5> (When this Unit's attack destroys an enemy Unit, deal the specified amount of damage to the first card in that opponent's shield area.)\n【Once per Turn】During your turn, when one of your other (Academy) Units receives damage from an enemy, place 1 EX Resource."
  },
  "GD04-019": {
    "pt": "<Breach 3> (Quando o ataque desta Unidade destruir uma Unidade inimiga, cause a quantidade especificada de dano à primeira carta na área de escudo daquele oponente.)\n【Destroyed】Olhe as 3 cartas do topo do seu deck. Você pode revelar 1 carta de Unidade (CB) de Lv.5 ou menor entre elas e adicioná-la à sua mão. Coloque as cartas restantes no fundo do seu deck em ordem aleatória.",
    "en": "<Breach 3> (When this Unit's attack destroys an enemy Unit, deal the specified amount of damage to the first card in that opponent's shield area.)\n【Destroyed】Look at the top 3 cards of your deck. You may reveal 1 (CB) Unit card that is Lv.5 or lower among them and add it to your hand. Return the remaining cards randomly to the bottom of your deck."
  },
  "GD04-020": {
    "pt": "【Once per Turn】Durante o seu turno, quando você jogar e ativar uma carta de Comando (Dawn of Fold) usando um EX Resource, compre 1 carta.",
    "en": "【Once per Turn】During your turn, when you play and activate a (Dawn of Fold) Command card using an EX Resource, draw 1."
  },
  "GD04-021": {
    "pt": "<Breach 3> (Quando o ataque desta Unidade destruir uma Unidade inimiga, cause a quantidade especificada de dano à primeira carta na área de escudo daquele oponente.)\nDurante o seu turno, quando você jogar e ativar uma carta de Comando (Dawn of Fold) usando um EX Resource, você pode parear aquela carta, a partir do seu lixo, com uma das suas Unidades com \"Gundam Lfrith\" no nome.",
    "en": "<Breach 3> (When this Unit's attack destroys an enemy Unit, deal the specified amount of damage to the first card in that opponent's shield area.)\nDuring your turn, when you play and activate a (Dawn of Fold) Command card using an EX Resource, you may pair that card from your trash with one of your Units with \"Gundam Lfrith\" in its card name."
  },
  "GD04-022": {
    "pt": "Todas as suas fichas de Unidade ganham <Breach 1>.\n\n(Quando o ataque desta Unidade destruir uma Unidade inimiga, cause a quantidade especificada de dano à primeira carta na área de escudo daquele oponente.)\n【During Link】Todas as Unidades de Lv.3 ou menor, exceto fichas de Unidade, entram em jogo descansadas.",
    "en": "All your Unit tokens gain <Breach 1>.\n\n(When this Unit's attack destroys an enemy Unit, deal the specified amount of damage to the first card in that opponent's shield area.)\n【During Link】All Units that are Lv.3 or lower other than Unit tokens are deployed rested."
  },
  "GD04-023": {
    "pt": "【Deploy】Escolha 1 das suas Unidades pareadas com um Piloto (Super Soldier). Durante este turno, ela pode escolher uma Unidade inimiga ativa de Lv.4 ou menor como alvo de ataque.",
    "en": "【Deploy】Choose 1 of your Units paired with a (Super Soldier) Pilot. During this turn, it may choose an active enemy Unit that is Lv.4 or lower as its attack target."
  },
  "GD04-024": {
    "pt": "【Deploy】Olhe as 3 cartas do topo do seu deck. Você pode revelar 1 carta de Unidade/carta de Comando (Academy) entre elas e adicioná-la à sua mão. Coloque as cartas restantes no fundo do seu deck em ordem aleatória.",
    "en": "【Deploy】Look at the top 3 cards of your deck. You may reveal 1 (Academy) Unit card/Command card among them and add it to your hand. Return the remaining cards randomly to the bottom of your deck."
  },
  "GD04-025": {
    "pt": "【Destroyed】Durante o seu turno, se você tiver outra Unidade (Dawn of Fold) em jogo, coloque 1 EX Resource.",
    "en": "【Destroyed】During your turn, if you have another (Dawn of Fold) Unit in play, place 1 EX Resource."
  },
  "GD04-026": {
    "pt": "【Deploy】Olhe a carta do topo do seu deck. Devolva-a ao topo do seu deck ou coloque-a no seu lixo.",
    "en": "【Deploy】Look at the top card of your deck. Return it to the top of your deck or place it into your trash."
  },
