  "ST02-010": {
    "pt": "【Burst】Adicione esta carta à sua mão.\n【During Link】Esta Unidade recebe AP+1 e HP+1.",
    "en": "【Burst】Add this card to your hand.\n【During Link】This Unit gets AP+1 and HP+1."
  },
  "ST02-011": {
    "pt": "【Burst】Adicione esta carta à sua mão.\n【During Link】Durante o seu turno, quando esta Unidade destrói uma Unidade inimiga com dano de batalha, compre 1 carta.",
    "en": "【Burst】Add this card to your hand.\n【During Link】During your turn, when this Unit destroys an enemy Unit with battle damage, draw 1."
  },
  "ST02-012": {
    "pt": "【Main】Escolha 1 das suas Unidades. Ela ganha <Breach 3> durante este turno.\n\n(Quando o ataque desta Unidade destrói uma Unidade inimiga, cause a quantidade de dano indicada à primeira carta da área de escudo daquele oponente.)\n【Pilot】[Trowa Barton]",
    "en": "【Main】Choose 1 of your Units. It gains <Breach 3> during this turn.\n\n(When this Unit's attack destroys an enemy Unit, deal the specified amount of damage to the first card in that opponent's shield area.)\n【Pilot】[Trowa Barton]"
  },
  "ST02-013": {
    "pt": "【Action】Durante esta batalha, as cartas da sua área de escudo não podem receber dano de Unidades inimigas que sejam Lv.4 ou menos.\n【Pilot】[Quatre Raberba Winner]",
    "en": "【Action】During this battle, your shield area cards can't receive damage from enemy Units that are Lv.4 or lower.\n【Pilot】[Quatre Raberba Winner]"
  },
  "ST02-014": {
    "pt": "【Burst】Ative o 【Main】 desta carta.\n【Main】/【Action】Escolha 1 Unidade inimiga com 5 ou menos de HP. Coloque-a em Rest.",
    "en": "【Burst】Activate this card's 【Main】.\n【Main】/【Action】Choose 1 enemy Unit with 5 or less HP. Rest it."
  },
  "ST02-015": {
    "pt": "【Burst】Faça o Deploy desta carta.\n【Deploy】Adicione 1 dos seus escudos à sua mão. Depois, olhe as 2 cartas do topo do seu deck e devolva 1 ao topo e 1 ao fundo.",
    "en": "【Burst】Deploy this card.\n【Deploy】Add 1 of your Shields to your hand. Then, look at the top 2 cards of your deck and return 1 to the top and 1 to the bottom."
  },
  "ST02-016": {
    "pt": "【Burst】Faça o Deploy desta carta.\n【Deploy】Adicione 1 dos seus escudos à sua mão. Depois, se for o seu turno, faça o Deploy de 1 ficha de Unidade [Tallgeese]((OZ)･AP4･HP2). Se for o seu turno e houver uma carta com \"Corsica Base\" no nome no seu lixo, em vez disso faça o Deploy de 2 fichas de Unidade [Leo]((OZ)･AP1･HP1).",
    "en": "【Burst】Deploy this card.\n【Deploy】Add 1 of your Shields to your hand. Then, if it is your turn, deploy 1 [Tallgeese]((OZ)･AP4･HP2) Unit token. If it is your turn and a card with \"Corsica Base\" in its card name is in your trash, deploy 2 [Leo]((OZ)･AP1･HP1) Unit tokens instead."
  },
  "ST03-001": {
    "pt": "【During Pair】Esta Unidade ganha <High-Maneuver>.\n\n(Esta Unidade não pode ser bloqueada.)\nDurante o seu turno, quando esta Unidade destrói uma carta da área de escudo inimiga com dano de batalha, escolha 1 Unidade inimiga. Cause 2 de dano a ela.",
    "en": "【During Pair】This Unit gains <High-Maneuver>.\n\n(This Unit can't be blocked.)\nDuring your turn, when this Unit destroys an enemy shield area card with battle damage, choose 1 enemy Unit. Deal 2 damage to it."
  },
