    "pt": "【Destroyed】Olhe as 3 cartas do topo do seu deck. Você pode revelar 1 carta de Unidade (Zeon)/(Neo Zeon) entre elas e adicioná-la à sua mão. Devolva as cartas restantes ao fundo do seu deck em ordem aleatória.",
    "en": "【Destroyed】Look at the top 3 cards of your deck. You may reveal 1 (Zeon)/(Neo Zeon) Unit card among them and add it to your hand. Return the remaining cards randomly to the bottom of your deck."
