    "pt": "【Burst】Adicione esta carta à sua mão.\n【Attack】Esta Unidade recebe AP+1 durante este turno. Se houver 7 ou mais cartas (CB) no seu lixo, todas as suas Unidades (CB) recebem AP+1 em vez disso.",
