  "ST09-003": {
    "pt": "<Breach 3> (Quando o ataque desta Unidade destruir uma Unidade inimiga, cause a quantidade especificada de dano à primeira carta na área de escudo daquele oponente.)\n【When Linked】Se houver 5 ou mais cartas roxas no seu lixo, cause 2 de dano a todas as Unidades com AP 5 ou menos.",
    "en": "<Breach 3> (When this Unit's attack destroys an enemy Unit, deal the specified amount of damage to the first card in that opponent's shield area.)\n【When Linked】If there are 5 or more purple cards in your trash, deal 2 damage to all Units with 5 or less AP."
  },
  "ST09-004": {
    "pt": "<Blocker> (Coloque esta Unidade em Rest para mudar o alvo do ataque para ela.)\nEnquanto uma Base aliada estiver em jogo, esta Unidade ganha <Suppression>.\n\n(O dano de um ataque aos escudos é causado às 2 primeiras cartas ao mesmo tempo.)",
    "en": "<Blocker> (Rest this Unit to change the attack target to it.)\nWhile a friendly Base in play, this Unit gains <Suppression>.\n\n(Damage to Shields by an attack is dealt to the first 2 cards simultaneously.)"
  },
  "ST09-005": {
    "en": "-"
  },
  "ST09-006": {
    "pt": "【Deploy】Se você fizer o Deploy desta Unidade a partir do seu lixo, escolha 1 Unidade inimiga de Lv.3 ou menor. Destrua-a.",
    "en": "【Deploy】If you deploy this Unit from your trash, choose 1 enemy Unit that is Lv.3 or lower. Destroy it."
  },
  "ST09-007": {
    "pt": "<Blocker> (Coloque esta Unidade em Rest para mudar o alvo do ataque para ela.)",
    "en": "<Blocker> (Rest this Unit to change the attack target to it.)"
  },
  "ST09-008": {
    "pt": "【Burst】Adicione esta carta à sua mão.\n【Attack】Se esta for uma Unidade (Minerva Squad), escolha 1 dos seus Recursos. Coloque-o como ativo.",
    "en": "【Burst】Add this card to your hand.\n【Attack】If this is a (Minerva Squad) Unit, choose 1 of your Resources. Set it as active."
  },
  "ST09-009": {
    "pt": "【Main】/【Action】Escolha 1 Unidade inimiga ativa com AP 4 ou menos. Destrua-a.",
    "en": "【Main】/【Action】Choose 1 active enemy Unit with 4 or less AP. Destroy it."
  },
  "ST09-010": {
    "pt": "【Burst】Faça o Deploy desta carta.\n【Deploy】Adicione 1 dos seus escudos à sua mão. Então, se for o seu turno, olhe as 2 cartas do topo do seu deck e devolva 1 ao topo. Coloque a carta restante no seu lixo.",
    "en": "【Burst】Deploy this card.\n【Deploy】Add 1 of your Shields to your hand. Then, if it is your turn, look at the top 2 cards of your deck and return 1 to the top. Place the remaining card into your trash."
  },
  "ST10-001": {
    "pt": "Quando esta Unidade destruir uma carta da área de escudo inimiga com dano de batalha, coloque-a como ativa. Ela não pode escolher o mesmo jogador inimigo ou a mesma equipe inimiga como alvo de ataque durante este turno.",
    "en": "When this Unit destroys an enemy shield area card with battle damage, set it as active. It can't choose the same enemy player or enemy team as its attack target during this turn."
  },
  "ST10-002": {
    "pt": "【Deploy･Development 2】Você pode exilar do jogo a quantidade especificada de cartas (G Generation) do seu lixo. Se fizer isso, ative o efeito a seguir:\n\n■Escolha 1 Unidade inimiga com HP 4 ou menos. Coloque-a em Rest.",
    "en": "【Deploy･Development 2】You may exile the specified number of (G Generation) cards in your trash from the game. If you do, activate the following effect:\n\n■Choose 1 enemy Unit with 4 or less HP. Rest it."
  },
  "ST10-003": {
    "en": "-"
  },
  "ST10-004": {
    "pt": "<Repair 2> (No fim do seu turno, esta Unidade recupera a quantidade especificada de HP.)",
    "en": "<Repair 2> (At the end of your turn, this Unit recovers the specified number of HP.)"
  },
  "ST10-005": {
    "en": "-"
  },
  "ST10-006": {
    "pt": "【During Pair】Durante o seu turno, quando esta Unidade destruir uma Unidade inimiga com dano de batalha, escolha 1 Unidade inimiga com HP 3 ou menos. Devolva-a à mão do dono.",
    "en": "【During Pair】During your turn, when this Unit destroys an enemy Unit with battle damage, choose 1 enemy Unit with 3 or less HP. Return it to its owner's hand."
  },
  "ST10-007": {
    "pt": "【When Linked･Development 2】Você pode exilar do jogo a quantidade especificada de cartas (G Generation) do seu lixo. Se fizer isso, ative o efeito a seguir:\n\n■Escolha 1 carta de Comando de Lv.4 ou menor do seu lixo. Adicione-a à sua mão.",
    "en": "【When Linked･Development 2】You may exile the specified number of (G Generation) cards in your trash from the game. If you do, activate the following effect:\n\n■Choose 1 Command card that is Lv.4 or lower from your trash. Add it to your hand."
  },
  "ST10-008": {
    "pt": "【Deploy･Development 2】Você pode exilar do jogo a quantidade especificada de cartas (G Generation) do seu lixo. Se fizer isso, ative o efeito a seguir:\n\n■Compre um número de cartas igual ao número de jogadores inimigos. Então, descarte o mesmo número de cartas que comprou com este efeito.",
    "en": "【Deploy･Development 2】You may exile the specified number of (G Generation) cards in your trash from the game. If you do, activate the following effect:\n\n■Draw a number of cards equal to the number of enemy players. Then, discard the same number of cards you drew with this effect."
  },
  "ST10-009": {
    "pt": "<Blocker> (Coloque esta Unidade em Rest para mudar o alvo do ataque para ela.)",
    "en": "<Blocker> (Rest this Unit to change the attack target to it.)"
  },
  "ST10-010": {
    "pt": "<Blocker> (Coloque esta Unidade em Rest para mudar o alvo do ataque para ela.)",
    "en": "<Blocker> (Rest this Unit to change the attack target to it.)"
  },
  "ST10-011": {
    "pt": "【Burst】Adicione esta carta à sua mão.\n【When Linked】Se 2 ou mais Unidades descansadas estiverem em jogo, escolha 1 Unidade inimiga com Lv. igual ou menor que o desta Unidade. Coloque-a em Rest.",
    "en": "【Burst】Add this card to your hand.\n【When Linked】If 2 or more rested Units are in play, choose 1 enemy Unit whose Lv. is equal to or lower than this Unit. Rest it."
  },
  "ST10-012": {
    "pt": "【Burst】Adicione esta carta à sua mão.\n【When Paired】Escolha 1 Unidade inimiga de Lv.5 ou menor. Ela recebe AP-2 durante este turno.",
    "en": "【Burst】Add this card to your hand.\n【When Paired】Choose 1 enemy Unit that is Lv.5 or lower. It gets AP-2 during this turn."
  },
  "ST10-013": {
    "pt": "【Burst】Adicione esta carta à sua mão.\n【Main】/【Action】Escolha 1 Unidade (G Generation) de Lv.5 ou maior. Ela recupera 2 de HP e recebe AP+2 durante este turno.",
    "en": "【Burst】Add this card to your hand.\n【Main】/【Action】Choose 1 (G Generation) Unit that is Lv.5 or higher. It recovers 2 HP and gets AP+2 during this turn."
  },
  "ST10-014": {
    "pt": "Ao jogar esta carta da sua mão, você pode descartar 1 carta de Unidade (G Generation). Se fizer isso, jogue esta carta como se tivesse Lv. e custo 2.\n【Main】Compre 2 cartas.",
    "en": "When playing this card from your hand, you may discard 1 (G Generation) Unit card. If you do, play this card as if it has 2 Lv. and cost.\n【Main】Draw 2."
  },
  "ST10-015": {
    "pt": "【Action】Se uma Unidade (G Generation) aliada estiver em jogo, escolha 1 Unidade inimiga. Ela recebe AP-3 durante esta batalha.\n【Pilot】[Claire Heathrow]",
    "en": "【Action】If a friendly (G Generation) Unit is in play, choose 1 enemy Unit. It gets AP-3 during this battle.\n【Pilot】[Claire Heathrow]"
  },
  "ST10-016": {
    "pt": "【Burst】Faça o Deploy desta carta.\n【Deploy】Adicione 1 dos seus escudos à sua mão. Então, todas as Unidades (G Generation) aliadas recuperam 1 de HP.",
    "en": "【Burst】Deploy this card.\n【Deploy】Add 1 of your Shields to your hand. Then, all friendly (G Generation) Units recover 1 HP."
  },
